<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/surveys';import {example} from '../utils/example';import {num} from '../utils/format';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import SurveyPlot from '../components/SurveyPlot.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const id=ref('demo-survey'),gid=ref('G01'),text=ref(JSON.stringify(example(),null,2));const survey=computed(()=>props.data.surveys.find(s=>s.id===id.value)||props.data.surveys[0]),group=computed(()=>survey.value?.groups.find(g=>g.group_id===gid.value)||survey.value?.groups[0]);const{busy,error,notice,act}=useAction();</script><template><Heading index="02 / SOURCE POINTS" title="原始点不丢，坐标先声明。" detail="只接受local_m局部投影米制；不把经纬度度数当米，不自动转换投影。点ID唯一，重复坐标留给口径决定。"/><div class="inline-selectors"><label>选择足迹测组<select aria-label="选择足迹测组" v-model="id"><option v-for="s in data.surveys" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>原始点组<select aria-label="原始点组" v-model="gid"><option v-for="g in survey?.groups" :key="g.group_id" :value="g.group_id">{{g.group_id}} {{g.name}} · {{g.points.length}}条</option></select></label></div><section v-if="group" class="evidence-section"><h2>{{group.name}}</h2><SurveyPlot :points="group.points" title="完整原始点 · 不按组选择删改源数据"/><details><summary>原始坐标台账 / {{group.points.length}}条</summary><div class="table-scroll"><table><thead><tr><th>点ID</th><th>x / m</th><th>y / m</th></tr></thead><tbody><tr v-for="p in group.points" :key="p.point_id"><td>{{p.point_id}}</td><td>{{num(p.x,8)}}</td><td>{{num(p.y,8)}}</td></tr></tbody></table></div></details></section><Empty v-else>导入一组明确local_m的点，保留原始点和重复记录。</Empty><section v-if="canWrite" class="form-section"><h2>导入局部米制测组</h2><p>JSON含name/source/coordinate_system=local_m/groups，每组group_id/name/points，点为point_id/x/y。每组1至300条，最多8组。</p><form @submit.prevent="act(async()=>{const s=await create(JSON.parse(text));await refresh();id=s.id;gid=s.groups[0].group_id},'测组已校验保存，原始坐标完整保留')"><label>米制点JSON<textarea aria-label="米制点JSON" rows="7" v-model="text"/></label><div class="actions"><button class="primary" :disabled="busy">校验并导入测组</button><button type="button" @click="text=JSON.stringify(example(),null,2)">恢复矩形示例</button></div></form><Notice :error="error" :notice="notice"/></section></template>